    },
    {
      "name": "LINQ to JSON",
      "description": "提供 JToken/JObject/JArray/JValue 等对象模型，支持以 LINQ 方式查询、构建和修改 JSON 文档，无需定义强类型类即可灵活操作 JSON 数据。",
      "evidence": ["Src/Newtonsoft.Json/Linq/JToken.cs", "Src/Newtonsoft.Json/Linq/JObject.cs", "Src/Newtonsoft.Json/Linq/JArray.cs"]
    },
    {
      "name": "JSON 读写器",
      "description": "提供高性能的流式 JSON 读写器（JsonTextReader/JsonTextWriter），支持异步读写、格式化输出、缩进控制等，是底层序列化引擎的基础。",
      "evidence": ["Src/Newtonsoft.Json/JsonReader.cs", "Src/Newtonsoft.Json/JsonTextWriter.cs", "Src/Newtonsoft.Json/JsonTextReader.cs"]
    },
    {
      "name": "BSON 格式支持",
      "description": "提供 BSON（Binary JSON）格式的读写器，支持将 JSON 数据以二进制格式序列化和反序列化。",
      "evidence": ["Src/Newtonsoft.Json/Bson/BsonReader.cs", "Src/Newtonsoft.Json/Bson/BsonWriter.cs"]
