      "evidence": ["Src/Newtonsoft.Json/Schema/JsonSchema.cs", "Src/Newtonsoft.Json/Schema/JsonSchemaGenerator.cs", "Src/Newtonsoft.Json/JsonValidatingReader.cs"]
